// This is not minified, but is named .min.js for plugin compatibility.
// See assets/js/attachment-cleanup.js for source.

(function($){
    $(function(){
        var $cleanupBtn = $('#cin-attach-delete-btn');
        var $cleanStaleBtn = $('#cin-attach-clean-stale-btn');
        var $summary = $('#cin-attach-summary');
        var $count = $('#cin-attach-orphaned');
        var $size = $('#cin-attach-orphaned-size');
        var $lastScan = $('#cin-attach-last-scan');
        var $staleCount = $('.contactin-attachment-cleanup-card').find('li:contains("Stale DB Entries")').find('.value');

        if (!$cleanupBtn.length) {
            return;
        }

        var originalLabel = $cleanupBtn.text();
        var originalStaleLabel = $cleanStaleBtn.length ? $cleanStaleBtn.text() : '';
        var lastScanFallback = $lastScan.length ? $lastScan.text() : '';

        $cleanupBtn.on('click', function(e){
            e.preventDefault();
            if (!confirm(cinAttachmentCleanup.i18n.deleteConfirm)) {
                return;
            }

            $cleanupBtn.prop('disabled', true).text('Cleaning...');
            $summary.text('');

            $.ajax({
                url: cinAttachmentCleanup.ajaxUrl,
                type: 'POST',
                data: {
                    action: 'contactin_maint_cleanup_orphaned_attachments',
                    nonce: cinAttachmentCleanup.nonce
                }
            }).done(function(response){
                if (response && response.success) {
                    $summary.text(response.data.message);

                    var stats = response.data && response.data.stats ? response.data.stats : {};
                    var count = parseInt(stats.count, 10);
                    if (isNaN(count)) {
                        count = 0;
                    }

                    var sizeBytes = parseInt(stats.size, 10);
                    if (isNaN(sizeBytes) || sizeBytes < 0) {
                        sizeBytes = 0;
                    }

                    var failedCount = Array.isArray(response.data.failed) ? response.data.failed.length : 0;

                    if ($count.length) {
                        $count.text(count);
                    }
                    if ($size.length) {
                        $size.text(formatMegabytes(sizeBytes));
                    }
                    if ($lastScan.length) {
                        var formattedLastScan = formatTimestamp(stats.last_scan, lastScanFallback);
                        if (formattedLastScan) {
                            $lastScan.text(formattedLastScan);
                            lastScanFallback = formattedLastScan;
                        }
                    }

                    var disableButton = count === 0 && failedCount === 0;
                    $cleanupBtn.prop('disabled', disableButton).text(originalLabel);

                    $('.contactin-attachment-cleanup-card .notice-warning').hide();
                } else {
                    var message = response && response.data && response.data.message
                        ? response.data.message
                        : cinAttachmentCleanup.i18n.error;
                    $summary.text(message);
                    $cleanupBtn.prop('disabled', false).text(originalLabel);
                }
            }).fail(function(){
                $summary.text(cinAttachmentCleanup.i18n.error);
                $cleanupBtn.prop('disabled', false).text(originalLabel);
            });
        });

        // Handle clean stale DB entries button
        if ($cleanStaleBtn.length) {
            $cleanStaleBtn.on('click', function(e){
                e.preventDefault();
                
                $cleanStaleBtn.prop('disabled', true).text('Cleaning...');
                $summary.text('');

                $.ajax({
                    url: cinAttachmentCleanup.ajaxUrl,
                    type: 'POST',
                    data: {
                        action: 'contactin_maint_clean_stale_db_entries',
                        nonce: cinAttachmentCleanup.nonce_clean_stale
                    }
                }).done(function(response){
                    if (response && response.success) {
                        $summary.text(response.data.message);
                        
                        if ($staleCount.length) {
                            $staleCount.text(response.data.remaining);
                        }
                        
                        // After 1 second, reload the page to show fresh scan results
                        setTimeout(function() {
                            location.reload();
                        }, 1000);
                    } else {
                        var message = response && response.data && response.data.message
                            ? response.data.message
                            : cinAttachmentCleanup.i18n.error;
                        $summary.text(message);
                        $cleanStaleBtn.prop('disabled', false).text(originalStaleLabel);
                    }
                }).fail(function(){
                    $summary.text(cinAttachmentCleanup.i18n.error);
                    $cleanStaleBtn.prop('disabled', false).text(originalStaleLabel);
                });
            });
        }

        function formatMegabytes(bytes) {
            var value = parseInt(bytes, 10);
            if (!value || value <= 0) {
                return '0.00 MB';
            }

            var mb = value / (1024 * 1024);
            return mb.toFixed(2) + ' MB';
        }

        function formatTimestamp(ts, fallback) {
            var intTs = parseInt(ts, 10);
            if (!intTs) {
                return fallback;
            }

            var date = new Date(intTs * 1000);
            if (isNaN(date.getTime())) {
                return fallback;
            }

            return date.toLocaleString();
        }
    });
})(jQuery);
